const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

const dynamicSchemaCache = new WeakMap<Record<string, unknown>, ValidateFunction>();

function getDynamicValidate(source: () => ToolDefinition, toolName: string): ValidateFunction {
  const resolved = source();
  const cached = dynamicSchemaCache.get(resolved.inputSchema);
  if (cached) return cached;
  const validate = compileSchema(toolName, resolved.inputSchema);
  dynamicSchemaCache.set(resolved.inputSchema, validate);
  return validate;
}

function formatValidationErrors(errors: ErrorObject[]): string {
  const messages = errors.map(err => {
    const path = err.instancePath ? `input${err.instancePath}` : 'input';
    if (err.keyword === 'required') {
      const missing = (err.params as {missingProperty: string}).missingProperty;
      return `${path} is missing required property: ${missing}`;
    }
    return `${path} ${err.message ?? 'is invalid'} (${err.keyword})`;
  });
  return `Tool input validation failed: ${messages.join('; ')}`;
}

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

